from mcp import ClientSession, StdioServerParameters
from mcp.client.stdio import stdio_client
import tools.lang as lang

USE_CN_MIRROR = True
CN_NPM_REGISTRY = "https://registry.npmmirror.com"

with open('mcp.json','r',encoding='utf-8') as f:
    MCP_SERVERS = json.load(f)

def _build_server_params(server_config: dict) -> StdioServerParameters:
    command = server_config["command"]
    args = list(server_config.get("args", []))
    env = dict(server_config.get("env") or {})
    if USE_CN_MIRROR and command == "npx":
        env.setdefault("NPM_CONFIG_REGISTRY", CN_NPM_REGISTRY)
    return StdioServerParameters(command=command, args=args, env=env)

async def _list_tools_async(server_config: dict) -> list[dict]:
    """内部异步实现：连接 MCP 服务器，返回可用工具列表。"""
    server = _build_server_params(server_config)
    async with stdio_client(server) as (read, write):
        async with ClientSession(read, write) as session:
            await session.initialize()
            tools_result = await session.list_tools()
            return [
                {
                    "name": tool.name,
                    "description": getattr(tool, "description", None),
                    "inputSchema": getattr(
                        tool,
                        "inputSchema",
                        getattr(tool, "input_schema", None),
                    ),
                }
                for tool in tools_result.tools
            ]

def list_tools(server_config: dict) -> list[dict]:
    """同步接口：连接 MCP 服务器，返回可用工具列表。"""
    return asyncio.run(_list_tools_async(server_config))

def get_mcp_list() -> list[dict]:
    result = []
    for server_name, server_config in MCP_SERVERS.items():
        try:
            tools = list_tools(server_config)
            for tool in tools:
                result.append({
                    "name": tool["name"],
                    "description": tool["description"] or "",
                })
        except:
            result = lang.lang['bot.mcp.getlistfailed']
    return result

async def _call_tool_async(
    server_config: dict,
    tool_name: str,
    arguments: dict | None = None,
) -> str:
    server = _build_server_params(server_config)
    async with stdio_client(server) as (read, write):
        async with ClientSession(read, write) as session:
            await session.initialize()
            result = await session.call_tool(
                tool_name,
                arguments=arguments or {},
            )
            text_parts = []
            for item in result.content:
                if hasattr(item, "text"):
                    text_parts.append(item.text)
                else:
                    text_parts.append(str(item))
            return "\n".join(text_parts)

def call_tool(
    server_config: dict,
    tool_name: str,
    arguments: dict | None = None,
) -> str:
    """同步接口：调用指定 MCP 工具并返回文本结果。"""
    return asyncio.run(_call_tool_async(server_config, tool_name, arguments or {}))

def main():
    config = MCP_SERVERS["chrome-devtools"]
    try:
        print("正在获取 MCP 工具列表 ...")
        tools = list_tools(config)
        print(f"发现 {len(tools)} 个工具：")
        for tool in tools:
            description = tool["description"] or ""
            print(f"  - {tool['name']}: {description}")

        if not tools:
            print("未发现可用工具。")
            return

        example_tool = tools[0]
        print(f"\n尝试调用示例工具：{example_tool['name']}")
        result = call_tool(config, example_tool["name"], {})
        print("调用结果：")
        print(result or "(无文本输出)")

    except FileNotFoundError:
        print("错误：未找到 npx，请安装 Node.js 并确保 npx 在 PATH 中。")
    except Exception as exc:
        print(f"运行失败：{type(exc).__name__}: {exc}")

if __name__ == "__main__":
    main()

